/**
 * Meson Enquirer — entry point. Creates the Discord client and wires events to their handlers; the logic lives in the modules imported below.
 *
 *  - Tickets (tickets.js): reads Ticket Tool's form embed and the user's later messages, posts each new swap and keeps it current (watch.js); a wallet-only ticket gets that wallet's unfinished swaps.
 *  - /meson-query (commands.js): look up one swap on demand.
 *
 * Needs the MESSAGE CONTENT privileged intent to read Ticket Tool's embed.
 */
// ----- Contents (generated by `npm run index` — do not edit) -----
// L38   Client
// L43     client
// L51   Events
// L59     forgetChannel()
// L65     on ClientReady
// L81     on MessageCreate
// L83     on InteractionCreate
// L86     on ChannelDelete
// L88     on ThreadDelete
// L91     on ShardReconnecting
// L93     on ShardDisconnect
// L95     on ShardResume
// L97     on ShardReady
// L104    on Error
// L109  Login
// ----- end of contents -----

import { Client, Events, GatewayIntentBits } from 'discord.js'
import { config } from './config.js'
import { chainCount, generatedAt } from './presets.js'
import { onTicketMessage } from './tickets.js'
import { onInteraction } from './commands.js'
import { forgetTicket } from './ticket-state.js'
import { stopWatchingChannel } from './watch.js'
import { recoverTickets } from './recover.js'
import { startExplorerCheck } from './explorer-check.js'
import { startPresetRefresh } from './meson.js'

// =============================================================================
//   Client
// =============================================================================

/** The one Discord client. Partials are not needed: only guild messages are read. */
const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent, // privileged — enable it in the dev portal
  ],
})

// =============================================================================
//   Events
// =============================================================================

/** Set once the first login is complete, so a later session can be told from the first. */
let started = false

/** A ticket's channel or thread was deleted (a closed ticket) — drop its state and watches with it. */
function forgetChannel (channel) {
  forgetTicket(channel.id)
  stopWatchingChannel(channel.id)
}

// Startup log, a warning when no staff roles are set, then restart recovery: every open ticket is rebuilt from the bot's own messages and followed again. Also starts the daily check that the explorer's status logic still matches our port, and the regular read of Meson's chain and token table.
client.once(Events.ClientReady, (c) => {
  started = true
  const { staffRoles } = config
  console.log(`logged in as ${c.user.tag}`)
  console.log(`presets: ${chainCount} chains (generated ${generatedAt})`)
  const categories = [...config.replyCategories].map((id) => c.channels.cache.get(id)?.name ?? `${id} (not found)`)
  console.log(`auto-reply in categories: ${categories.join(', ')}`)
  if (!staffRoles.size) {
    console.warn('! no STAFF_ROLE_IDS set, so swap IDs pasted by staff in tickets get looked up too')
  }
  recoverTickets(c).catch((err) => console.error('restart recovery failed —', err.message))
  startExplorerCheck()
  startPresetRefresh()
})

// Ticket auto-reply (Ticket Tool form + user messages).
client.on(Events.MessageCreate, onTicketMessage)
// Slash commands.
client.on(Events.InteractionCreate, onInteraction)

// A closed ticket's channel is deleted.
client.on(Events.ChannelDelete, forgetChannel)
// Threads have their own delete event, and they count as tickets too.
client.on(Events.ThreadDelete, forgetChannel)

// Connection drops are normal and discord.js reconnects by itself; logged so the log shows whether the bot was connected.
client.on(Events.ShardReconnecting, (id) => console.warn(`discord connection ${id} lost, reconnecting`))
// The connection closed for good (for example a rejected token): discord.js will not reconnect by itself.
client.on(Events.ShardDisconnect, (event, id) => console.error(`!! discord connection ${id} closed (code ${event.code})`))
// A resumed connection replays what was missed, so nothing more is needed.
client.on(Events.ShardResume, (id, replayed) => console.log(`discord connection ${id} resumed (${replayed} events replayed)`))
// A new session after a long drop does not replay anything: catch up from each ticket's history, as after a restart.
client.on(Events.ShardReady, (id) => {
  if (!started) return
  console.warn(`discord connection ${id} started a new session — catching up on every ticket`)
  recoverTickets(client).catch((err) => console.error('catching up after a reconnect failed —', err.message))
})

// Discord connection errors: log them. Without a listener Node treats an 'error' event as fatal, and a crash would drop every watch.
client.on(Events.Error, (err) => console.error('discord client error —', err.message))

// Last line of defence: a stray failed reply must not crash the process (Node exits on an unhandled rejection) and lose every watch.
process.on('unhandledRejection', (err) => console.error('unhandled error —', err?.stack ?? err))

// =============================================================================
//   Login
// =============================================================================

client.login(config.token)
